<?php

declare(strict_types=1);

namespace MSDev\DoctrineFMDataAPIDriver\Tests\Functional\Entity;

use Doctrine\ORM\Mapping as ORM;
use MSDev\DoctrineFMDataAPIDriver\Id\FMIdentityGenerator;

/**
 * Maps the API_Note layout. Its key is generated by FileMaker, like Keyword's, and the foreign key is a plain
 * column: the driver does not support SQL joins.
 */
#[ORM\Entity]
#[ORM\Table(name: 'API_Note')]
class Note
{
    #[ORM\Column(name: 'rec_id', type: 'integer')]
    private ?int $recordId = null;

    #[ORM\Id]
    #[ORM\Column(name: 'ID', type: 'string', length: 255, insertable: false)]
    #[ORM\GeneratedValue(strategy: 'CUSTOM')]
    #[ORM\CustomIdGenerator(class: FMIdentityGenerator::class)]
    private ?string $id = null;

    #[ORM\Column(name: 'ID_Keyword', type: 'string', length: 255, nullable: true)]
    private ?string $keywordId = null;

    #[ORM\Column(name: 'Text', type: 'string', nullable: true)]
    private ?string $text = null;

    public function __construct(?string $keywordId = null, ?string $text = null)
    {
        $this->keywordId = $keywordId;
        $this->text = $text;
    }

    public function getRecordId(): ?int { return $this->recordId; }
    public function getId(): ?string { return $this->id; }
    public function getKeywordId(): ?string { return $this->keywordId; }
    public function getText(): ?string { return $this->text; }
    public function setText(?string $text): self { $this->text = $text; return $this; }
}
